<?php defined( 'ABSPATH' ) || exit; $services = post_type_exists( 'ny_service' ) ? get_posts( array( 'post_type' => 'ny_service', 'posts_per_page' => 6, 'post_status' => 'publish', 'orderby' => array( 'menu_order' => 'ASC', 'title' => 'ASC' ) ) ) : array(); ?><section class="nytt01-section nytt01-section--muted"><div class="nytt01-container"><header class="nytt01-section-header"><div><p class="nytt01-eyebrow"><?php esc_html_e( 'Services', 'nolan-young-theme-template-01' ); ?></p><h2><?php esc_html_e( 'Capabilities organized around real outcomes', 'nolan-young-theme-template-01' ); ?></h2></div></header><div class="nytt01-card-grid"><?php if ( $services ) : foreach ( $services as $service ) : ?><article class="nytt01-service-card"><h3><a href="<?php echo esc_url( get_permalink( $service ) ); ?>"><?php echo esc_html( get_the_title( $service ) ); ?></a></h3><p><?php echo esc_html( wp_trim_words( get_the_excerpt( $service ), 24 ) ); ?></p></article><?php endforeach; else : foreach ( array( 'WordPress strategy', 'Experience design', 'Theme engineering', 'Performance optimization', 'Accessibility remediation', 'Ongoing maintenance' ) as $fallback ) : ?><article class="nytt01-service-card"><h3><?php echo esc_html( $fallback ); ?></h3><p><?php esc_html_e( 'Publish service entries to replace this starter content.', 'nolan-young-theme-template-01' ); ?></p></article><?php endforeach; endif; ?></div></div></section>
